const b = $('Webhook').first().json.body;
if (!b || !b.id) { throw new Error('Falta el id del proyecto'); }
const row = { id: String(b.id) };
const campos = ['nombre','cliente','agencia','productora','director','ep_nombre','ep_email','prod_nombre','prod_email','coord_nombre','coord_email','status','year','month','tareas_json','asignaciones_json','links_json','taskDates_json','sintesis','storyboard_url','tratamiento_url','checklist_json','tracker_json', 'equipo_json'];
campos.forEach(f => {
  if (b[f] !== undefined && b[f] !== null) {
    row[f] = typeof b[f] === 'string' ? b[f] : JSON.stringify(b[f]);
  }
});
if (b.tareas !== undefined && b.tareas_json === undefined) row.tareas_json = JSON.stringify(b.tareas);
if (b.asignaciones !== undefined && b.asignaciones_json === undefined) row.asignaciones_json = JSON.stringify(b.asignaciones);
if (b.links !== undefined && b.links_json === undefined) row.links_json = JSON.stringify(b.links);
if (b.taskDates !== undefined && b.taskDates_json === undefined) row.taskDates_json = JSON.stringify(b.taskDates);
return [{ json: row }];

const b = $('Webhook').first().json.body || {};
if (!b.status || !b.id) return [];
return [{ json: { id: String(b.id), status: String(b.status) } }];

const cambio = $('\u00bfCambi\u00f3 la etapa?').first().json;
const filas = $('Leer Projects').all().map(i => i.json);
const p = filas.find(r => String(r.id) === cambio.id);
if (!p) return [];
const LABELS = { por_activarse: 'Pre-producci\u00f3n', activo: 'Ejecutando', entregando: 'Entregando', cierre: 'Listo para cierre', completado: 'Completado' };
const EMOJI = { activo: '\ud83d\udfe2', entregando: '\ud83d\udce6', cierre: '\ud83d\udd34', completado: '\ud83c\udfc1' };
const label = LABELS[cambio.status] || cambio.status;
const emoji = EMOJI[cambio.status] || '\ud83d\udd01';
const out = [];

/* 1. Aviso en el canal -avisos del proyecto (igual que antes) */
const canal = String(p.discord_avisos_id || '').replace(/^'+/, '');
if (canal) out.push({ json: { channelId: canal, content: emoji + ' **' + (p.nombre || 'Proyecto') + '** pas\u00f3 a **' + label + '**' } });

/* 2. Hito en el canal general, solo etapas principales, con m\u00ednima info de fechas */
const HITOS_GENERAL = ['activo', 'entregando', 'cierre', 'completado'];
const general = String($('CONFIG').first().json.discordGeneralId || '').trim();
if (general && general !== 'PEGAR_ID_DEL_CANAL_GENERAL' && HITOS_GENERAL.includes(cambio.status)) {
  const cal = $('Leer Calendario').all().map(i => i.json).filter(r => r && String(r.project_id) === cambio.id);
  const fases = cal.filter(r => (r.tipo || 'fase') !== 'hito');
  const hitos = cal.filter(r => r.tipo === 'hito');
  const dmy = s => { const t = String(s || '').slice(0, 10).split('-'); return t.length === 3 ? t[2] + '/' + t[1] : String(s || ''); };
  const inicios = fases.map(r => r.inicio).filter(Boolean).sort();
  const fines = fases.map(r => r.fin || r.inicio).filter(Boolean).sort();
  const partes = [];
  if (inicios.length && fines.length) partes.push('\ud83d\udcc5 ' + dmy(inicios[0]) + ' al ' + dmy(fines[fines.length - 1]));
  if (cambio.status !== 'completado') {
    const hoy = new Date().toISOString().slice(0, 10);
    const prox = hitos.filter(h => (h.inicio || '') >= hoy).sort((a, b) => String(a.inicio).localeCompare(String(b.inicio)))[0];
    if (prox) partes.push('Pr\u00f3ximo hito: ' + (prox.fase || 'Hito') + ' ' + dmy(prox.inicio));
  }
  const lineas = [emoji + ' **' + (p.nombre || 'Proyecto') + '** \u2192 ' + label];
  if (partes.length) lineas.push(partes.join(' \u00b7 '));
  out.push({ json: { channelId: general, content: lineas.join('\n') } });
}
return out;

const b = $('Webhook').first().json.body || {};
const esActivacion = b.status === 'activo';
const esEquipo = b.asignaciones_json !== undefined && b.status === undefined;
if ((!esActivacion && !esEquipo) || !b.id) return [];
return [{ json: { id: String(b.id), motivo: esActivacion ? 'activacion' : 'equipo' } }];

const meta = $('Roster: metadata').first().json || {};
const hojas = meta.sheets || [];
const hoja = hojas.find(s => s.properties && s.properties.sheetId === 0) || hojas[0];
if (!hoja) return [{ json: { urlLeer: '' } }];   /* sin roster el flujo sigue, solo pierde el fallback */
const base = 'https://sheets.googleapis.com/v4/spreadsheets/' + $('CONFIG').first().json.rosterSheetId + '/values/';
return [{ json: { urlLeer: base + encodeURIComponent(hoja.properties.title + '!A1:Z2000') } }];

const gate = $('\u00bfDar accesos?').first().json;
const filas = $('Projects (accesos)').all().map(i => i.json).filter(r => r && r.id);
const p = filas.find(r => String(r.id) === gate.id);
if (!p) return [];
const status = String(p.status || '');
if (gate.motivo === 'equipo' && !['activo','entregando','cierre'].includes(status)) return [];
const catId = String(p.discord_category_id || '').replace(/^'+/, '');
const generalId = String(p.discord_avisos_id || '').replace(/^'+/, '');
if (!catId && !generalId) return [];
let asigs = {}; try { asigs = JSON.parse(p.asignaciones_json || '{}'); } catch (e) {}
const norm = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const normTag = s => String(s || '').toLowerCase().replace(/^@+/, '').replace(/[^a-z0-9._]/g, '');
/* fallback: tag de discord desde el roster, por nombre */
const rosterTag = new Map();
try {
  const vals = ($('Roster: leer').first().json || {}).values || [];
  if (vals.length) {
    const heads = vals[0].map(norm);
    const iN = heads.findIndex(h => h.includes('nombre'));
    const iD = heads.findIndex(h => h.includes('discord'));
    if (iN >= 0 && iD >= 0) vals.slice(1).forEach(v => {
      const n = norm((v || [])[iN]); const d = normTag((v || [])[iD]);
      if (n && d) rosterTag.set(n, d);
    });
  }
} catch (e) {}
/* canales del proyecto */
const canales = $('Discord: canales del guild').all().map(i => i.json).filter(c => c && c.id && String(c.parent_id || '') === catId);
const canalPor = suf => { const c = canales.find(x => String(x.name || '').endsWith('-' + suf)); return c ? String(c.id) : ''; };
const MAPA = { 'Online': 'online', 'VFX': 'vfx', 'Color': 'color' };   /* espejo del workflow 3 */
/* miembros del servidor: username normalizado -> id */
const porUser = new Map();
$('Discord: miembros').all().map(i => i.json).filter(m => m && m.user).forEach(m => {
  porUser.set(normTag(m.user.username), String(m.user.id));
  if (m.user.global_name && !porUser.has(normTag(m.user.global_name))) porUser.set(normTag(m.user.global_name), String(m.user.id));
});
const grants = new Map(), conAcceso = new Set(), sinMatch = new Set(), sinTag = new Set();
Object.entries(asigs).forEach(([tarea, rows]) => {
  (rows || []).forEach(r => {
    if (!r || (r.estado && r.estado !== 'confirmado')) return;   /* solo confirmados (sin estado = agregado directo) */
    const nombre = String(r.nombre || '').trim();
    if (!nombre) return;
    const tag = normTag(r.discord) || rosterTag.get(norm(nombre)) || '';
    if (!tag) { sinTag.add(nombre); return; }
    const uid = porUser.get(tag);
    if (!uid) { sinMatch.add(nombre + ' (' + tag + ')'); return; }
    conAcceso.add(nombre);
    const chs = [];
    if (generalId) chs.push({ ch: generalId, allow: '3072' });   /* ver + escribir */
    if (catId) chs.push({ ch: catId, allow: '1024' });           /* ver la categoria para que quede agrupado */
    const suf = MAPA[tarea];
    const tCh = suf ? canalPor(suf) : '';
    if (tCh) chs.push({ ch: tCh, allow: '3072' });
    chs.forEach(x => grants.set(x.ch + '|' + uid, { channelId: x.ch, userId: uid, allow: x.allow }));
  });
});
return [{ json: { motivo: gate.motivo, nombreProyecto: p.nombre || 'Proyecto', generalId,
  grants: [...grants.values()], conAcceso: [...conAcceso], sinMatch: [...sinMatch], sinTag: [...sinTag] } }];

const a = $('Armar accesos').first().json;
if (a.motivo !== 'activacion' || !a.generalId) return [];
if (!a.conAcceso.length && !a.sinMatch.length && !a.sinTag.length) return [];
const lineas = ['\ud83d\udd13 **' + a.nombreProyecto + '**: accesos del equipo confirmado'];
if (a.conAcceso.length) lineas.push('Con acceso: ' + a.conAcceso.join(', '));
if (a.sinMatch.length) lineas.push('\u26a0 No est\u00e1n en el servidor o el tag no coincide: ' + a.sinMatch.join(', '));
if (a.sinTag.length) lineas.push('\u26a0 Sin tag de Discord cargado: ' + a.sinTag.join(', '));
return [{ json: { channelId: a.generalId, content: lineas.join('\n').slice(0, 1900) } }];

const b = $('Webhook').first().json.body || {};
/* El hub manda body.mails cuando se suma gente al proyecto ya creado y se le
   quiere mandar la propuesta. Mismo formato que en wf3: rol, to, nombre,
   enviar, subject, html. Sin esa clave esta rama no hace nada, así que los
   updates normales (etapa, equipo, calendario) no disparan ningún mail. */
if (!Array.isArray(b.mails)) return [];
return b.mails
  .filter(m => m && m.to && m.html && m.enviar !== false)
  .map(m => ({ json: {
    to: String(m.to).trim(),
    subject: m.subject || ('Propuesta TEAM23 \u2014 ' + (b.nombre || '')),
    html: m.html
  } }));

